  "literacy.tutorial.title": "Kalakriti मा स्वागत छ — यो कसरी काम गर्दछ",
  "literacy.tutorial.subtitle": "कारीगरहरूको लागि डिजाइन गरिएको। प्राविधिक कम्प्यूटर कौशल बिना आफ्नो शिल्प भारत भर बेच्नुहोस्।",
  "literacy.tutorial.step1Title": "1. आफ्नो मातृभाषामा बोल्नुहोस्",
  "literacy.tutorial.step1Desc": "टाइप गर्न आवश्यक छैन। तपाईंको शिल्प वर्णन गर्ने छोटो आवाज नोट रेकर्ड गर्नुहोस्। हाम्रो AI ले लिस्टिङ लेख्छ र लेख्छ।",
  "literacy.tutorial.step2Title": "2. स्वचालित एआई स्टुडियो प्रकाश",
  "literacy.tutorial.step2Desc": "आफ्नो मोबाइल मा साधारण फोटो खिच्नुहोस्। हाम्रो AI ले व्यस्त कार्यशाला पृष्ठभूमिहरू सफा गर्छ र प्राकृतिक प्रकाशलाई सन्तुलनमा राख्छ।",
  "literacy.tutorial.step3Title": "3. उचित मूल्य सल्लाह",
  "literacy.tutorial.step3Desc": "हामी तपाइँको कच्चा माल र दैनिक श्रम लागत गणना गर्छौं ताकि तपाइँ तपाइँको सही कमाई भन्दा कम बेच्नुहुन्न।",
  "literacy.tutorial.step4Title": "4. प्रत्यक्ष बैंक भुक्तानी",
  "literacy.tutorial.step4Desc": "खरिदकर्ताहरूले DBT मार्फत तपाईंको प्रमाणित बैंक खातामा सिधै भुक्तानी गर्छन्। शून्य मध्यस्थ शुल्क।",
  "literacy.tutorial.close": "बुझ्यो, सुरु गरौं",
  "literacy.tutorial.open": "यो कसरी काम गर्दछ",
